#include <torch/extension.h>
#include <c10/hip/HIPStream.h>
#include <miopen/miopen.h>

void check_miopen(miopenStatus_t status, const char* operation) {
    TORCH_CHECK(status == miopenStatusSuccess, operation, " failed: ", miopenGetErrorString(status));
}

torch::Tensor run(const torch::Tensor& x, const torch::Tensor& y) {
    TORCH_CHECK(x.is_cuda() && y.is_cuda(), "inputs must be HIP tensors");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32 && y.scalar_type() == torch::kFloat32, "inputs must be float32");
    TORCH_CHECK(x.is_contiguous() && y.is_contiguous() && x.sizes() == y.sizes(), "inputs must be contiguous and shape-compatible");
    auto output = torch::empty_like(x);
    miopenHandle_t handle = nullptr;
    miopenTensorDescriptor_t descriptor = nullptr;
    check_miopen(miopenCreate(&handle), "miopenCreate");
    check_miopen(miopenSetStream(handle, c10::hip::getCurrentHIPStream()), "miopenSetStream");
    check_miopen(miopenCreateTensorDescriptor(&descriptor), "miopenCreateTensorDescriptor");
    check_miopen(miopenSet4dTensorDescriptor(descriptor, miopenFloat, 1, 1, 1, x.numel()), "miopenSet4dTensorDescriptor");
    const float alpha = 1.0f;
    const float beta = 0.0f;
    check_miopen(miopenOpTensor(handle, miopenTensorOpAdd, &alpha, descriptor, x.data_ptr<float>(), &alpha, descriptor, y.data_ptr<float>(), &beta, descriptor, output.data_ptr<float>()), "miopenOpTensor");
    check_miopen(miopenDestroyTensorDescriptor(descriptor), "miopenDestroyTensorDescriptor");
    check_miopen(miopenDestroy(handle), "miopenDestroy");
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
    module.def("run", &run, "gfx1200 MIOpen tensor addition");
}
